    var view: AsukaPlatformView { impl.view }

    func set(_ name: String, _ value: AsukaNativeValue) {
        guard case .bytes(let d) = value else { return }
        var r = AsukaNativeReader(d)
        switch name {
        case "Type":
            let v = ButtonType(rawValue: r.int())
            if !r.failed { impl.setType(v) }
        case "Variant":
