            if !r.failed { impl.setVariant(v) }
        case "CornerRadius":
            let v = r.float64()
            if !r.failed { impl.setCornerRadius(v) }
        case "Networks":
            let v = Wire.readSliceNetwork(&r)
            if !r.failed { impl.setNetworks(v) }
        default: break
