                    let v = try await o.available(request: request)
                    Wire.writeAvailability(&w, v)
                    done(.success(w))
                } catch {
                    done(.failure(error))
                }
            }
        case (0, 2): // Wallets.Pay
            let o = object as! any Wallets
            let request = Wire.readSheet(&r)
            let askedID = r.callback()
            let asked: (Ask) -> Void = { a0 in
                var w = AsukaNativeWriter()
                Wire.writeAsk(&w, a0)
                AsukaNative.notify(askedID, w)
            }
            guard !r.failed else { done(.failure(AsukaNativeError.malformed)); return nil }
            return _Concurrency.Task {
                do {
                    var w = AsukaNativeWriter.ok()
                    let v = try await o.pay(request: request, asked: asked)
                    Wire.writePayment(&w, v)
                    done(.success(w))
                } catch {
                    done(.failure(error))
                }
            }
        case (0, 4): // Wallets.SetUp
            let o = object as! any Wallets
            guard !r.failed else { done(.failure(AsukaNativeError.malformed)); return nil }
            return _Concurrency.Task {
                do {
                    var w = AsukaNativeWriter.ok()
                    try await o.setUp()
                    done(.success(w))
                } catch {
                    done(.failure(error))
                }
            }
        default:
            done(.failure(AsukaNativeError.unsupported("no method \(iface).\(method)")))
            return nil
        }
    }

    @MainActor public static func makeView(_ name: String, _ ctx: AsukaNativeContext) -> AsukaNativeView? {
        switch name {
        case "PayButton": return AsukaViewPayButton(ctx)
        default: return nil
        }
    }
